x = [2, 8, 9, 12, 4, 14, 10, 15, 13, 7, 6, 3, 11, 1, 5, 0]
n = len(x)
print("Permutation check:", sorted(x) == list(range(n)))
vectors = {}
for i in range(n):
    for j in range(i+1, n):
        dr = x[j] - x[i]
        dc = j - i
        if (dr, dc) in vectors:
            print(f"Duplicate: ({dr},{dc}) from cols {i},{j} and {vectors[(dr,dc)]}")
        vectors[(dr, dc)] = (i, j)
print(f"Total vectors: {len(vectors)}, expected: {n*(n-1)//2}")
print("All distinct:", len(vectors) == n*(n-1)//2)
